package org.nigeriag2p.field;
import android.content.*;import android.security.keystore.*;import android.util.Base64;import java.security.KeyStore;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;import org.json.*;import java.io.IOException;
final class FieldStore {
 static final Object LOCK=new Object();
 static javax.crypto.SecretKey key() throws Exception {KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);if(!ks.containsAlias("field-demo-key")){KeyGenerator kg=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");kg.init(new KeyGenParameterSpec.Builder("field-demo-key",KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());kg.generateKey();}return (javax.crypto.SecretKey)ks.getKey("field-demo-key",null);}
 static JSONObject read(Context c)throws Exception {SharedPreferences p=c.getSharedPreferences("MainActivity",0);String data=p.getString("data","");if(data.isEmpty()){JSONObject empty=new JSONObject();empty.put("records",new JSONArray());empty.put("endpoint","");return empty;}Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Base64.decode(p.getString("iv",""),2)));return new JSONObject(new String(cipher.doFinal(Base64.decode(data,2)),"UTF-8"));}
 static void write(Context c,JSONObject all)throws Exception {Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key());byte[] ct=cipher.doFinal(all.toString().getBytes("UTF-8"));if(!c.getSharedPreferences("MainActivity",0).edit().putString("iv",Base64.encodeToString(cipher.getIV(),2)).putString("data",Base64.encodeToString(ct,2)).commit())throw new IOException("Save failed");}
 static void mergeSent(JSONObject older,JSONArray records)throws Exception {JSONArray current=older.optJSONArray("records");if(current==null)return;for(int i=0;i<records.length();i++){JSONObject target=records.getJSONObject(i);for(int j=0;j<current.length();j++){JSONObject live=current.getJSONObject(j);if(target.optString("id").equals(live.optString("id"))&&live.optString("status").equals("sent")){target.put("status","sent");target.remove("sync_error");}}}}
}
